H.background();
const g = 9.8;
const L = Math.max(P.L, 0.1);
const T = 2 * Math.PI * Math.sqrt(L / g);
const w = (2 * Math.PI) / T;
const A = 0.35;
const theta = A * Math.cos(w * t);
H.text("Simple pendulum: T = 2π √(L/g)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Period depends on length, not mass or amplitude (small angle)", 24, 52, { color: H.colors.sub, size: 13 });
const px = 450, py = 110;
const Lmax = 4.0;
const lenPx = 80 + (L / Lmax) * 320;
const bx = px + lenPx * Math.sin(theta);
const by = py + lenPx * Math.cos(theta);
H.line(px, py, px, py + lenPx + 20, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.circle(px, py, 6, { fill: H.colors.axis });
H.line(px, py, bx, by, { color: H.colors.sub, width: 2 });
H.circle(bx, by, 22, { fill: H.colors.accent, stroke: H.colors.ink, width: 2 });
const arcPts = [];
for (let i = 0; i <= 20; i++) {
  const a = -A + (2 * A) * (i / 20);
  arcPts.push([px + lenPx * Math.sin(a), py + lenPx * Math.cos(a)]);
}
H.path(arcPts, { color: H.colors.violet, width: 1, dash: [3, 3] });
H.text("θ(t)", bx + 24, by, { color: H.colors.sub, size: 12 });
H.text("L = " + L.toFixed(2) + " m", 24, 76, { color: H.colors.sub, size: 13 });
H.text("T = " + T.toFixed(2) + " s    θ = " + (theta * 180 / Math.PI).toFixed(1) + "°", 24, 96, { color: H.colors.sub, size: 13 });
